pm.test("Health endpoint returns HTTP 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Application reports healthy status", function () {
    const response = pm.response.json();
    pm.expect(response.ok).to.eql(true);
});

pm.test("Login returns HTTP 303", function () {
    pm.response.to.have.status(303);
});

pm.test("User redirects to dashboard", function () {
    const location = pm.response.headers.get("Location");
    pm.expect(location).to.include("/app");
});

pm.test("Authentication cookie is created", function () {
    const setCookie = pm.response.headers.get("Set-Cookie");
    pm.expect(setCookie).to.include("access_token=");
});

pm.test("Submission returns HTTP 201", function () {
    pm.response.to.have.status(201);
});

pm.test("Submission has correct information", function () {
    const data = pm.response.json();

    pm.expect(data.title).to.eql("Postman Test Research");
    pm.expect(data.abstract).to.eql(
        "Testing research submission through Postman."
    );
    pm.expect(data.submission_type).to.eql("Poster");
});

pm.test("Submission status is Submitted", function () {
    const data = pm.response.json();

    pm.expect(data.status).to.eql("Submitted");
});

pm.test("Submission has an ID and timestamp", function () {
    const data = pm.response.json();

    pm.expect(data.id).to.be.a("number");
    pm.expect(data.submitted_at).to.exist;
});

// Save the submission ID for later API tests
if (pm.response.code === 201) {
    const data = pm.response.json();
    pm.collectionVariables.set("submissionId", data.id);
}

pm.test("Missing title returns HTTP 422", function () {
    pm.response.to.have.status(422);
});

pm.test("Validation error is returned", function () {
    const data = pm.response.json();

    pm.expect(data.detail).to.exist;
    pm.expect(data.detail).to.be.an("array");

    const titleError = data.detail.some(function (error) {
        return error.loc && error.loc.includes("title");
    });

    pm.expect(titleError).to.be.true;
});

pm.test("Submissions API returns HTTP 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response is a JSON array", function () {
    const data = pm.response.json();
    pm.expect(data).to.be.an("array");
});

pm.test("Each submission contains required fields", function () {
    const data = pm.response.json();

    data.forEach(function (submission) {
        pm.expect(submission).to.have.property("id");
        pm.expect(submission).to.have.property("title");
        pm.expect(submission).to.have.property("abstract");
        pm.expect(submission).to.have.property("submission_type");
        pm.expect(submission).to.have.property("status");
        pm.expect(submission).to.have.property("submitted_at");
    });
});

