pm.test("Review decision returns HTTP 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Review decision is Accepted", function () {
    const data = pm.response.json();
    pm.expect(data.decision).to.eql("Accepted");
});

pm.test("Review feedback is saved correctly", function () {
    const data = pm.response.json();
    pm.expect(data.feedback).to.eql("Postman review approved");
});

pm.test("Review belongs to the correct submission", function () {
    const data = pm.response.json();
    const submissionId = pm.collectionVariables.get("submissionId");

    pm.expect(String(data.submission_id)).to.eql(String(submissionId));
    pm.expect(data.id).to.be.a("number");
});

