pm.test("Researcher can see accepted review", function () {
    const data = pm.response.json();

    pm.expect(data.review).to.not.be.null;
    pm.expect(data.review.decision).to.eql("Accepted");
    pm.expect(data.review.feedback).to.eql("Postman review approved");
});

pm.test("Researcher can see presentation details", function () {
