    pm.expect(data.presentation).to.not.be.null;
    pm.expect(data.presentation.date).to.eql("2026-11-20");
    pm.expect(data.presentation.time).to.include("10:00");
    pm.expect(data.presentation.location).to.eql("Conference Room A");
});

pm.test("Submission timeline includes Scheduled", function () {
    const data = pm.response.json();

    pm.expect(data.timeline).to.be.an("array");

    const labels = data.timeline.map(step => step.label);
    pm.expect(labels).to.include("Scheduled");
});

